mapper.select:
		SELECT distinct ${validatedColumnName} FROM ${validatedTableName}
			where ${validatedColumnName} is not null and ${validatedColumnName} !=''

            and ${validatedConditionColumnName}=#{conditionValue}


			and level=#{level} 


			and parent=#{parent} 

		order by ${validatedColumnName} desc

SELECT count(1) FROM ${validatedTableName}
	where 1=1 


		     and ${validatedColumnName} >= #{remindstart}


		     and ${validatedColumnName} <= #{remindend}




		     and ${validatedColumnName} >= str_to_date(#{remindstart},'%Y-%m-%d')


		     and ${validatedColumnName} <= str_to_date(#{remindend},'%Y-%m-%d')
